  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned DEFAULT NULL,
  `urun_adi` varchar(255) NOT NULL,
  `cas_no` varchar(255) DEFAULT NULL,
  `tedarikci` varchar(255) DEFAULT NULL,
  `fiziksel_hal` varchar(255) DEFAULT NULL,
  `kullanim_alani` varchar(255) DEFAULT NULL,
  `depolama` text,
  `ghs` json DEFAULT NULL,
  `aciklama` text,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `kimyasal_kutuphanesi_user_id_urun_adi_index` (`user_id`,`urun_adi`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

